from collections.abc import Iterator, Sequence
from typing import TypeVar

T = TypeVar("T")

def chunks(items: Sequence[T], n: int) -> Iterator[Sequence[T]]:
    if n <= 0:
        raise ValueError("n must be > 0")
    for i in range(0, len(items), n):
        yield items[i : i + n]
