from collections.abc import Iterator
from pathlib import Path

def grep(path: Path, needle: str) -> Iterator[str]:
    with path.open(encoding="utf-8", errors="replace") as fh:
        for line in fh:
            if needle in line:
                yield line.rstrip("\n")
